/* Scoped industrial presentation for the original PDF guided proposal desk. */
.pdf-guided-editor{color:#202020;background:#fafafa;border:1px solid #bdbdbd;border-radius:3px;padding:1rem;margin:1rem 0;font:400 14px/1.5 system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;max-width:100%;min-width:0}
.pdf-guided-editor *{box-sizing:border-box}
.pdf-guided-editor h3{font-size:1.15rem;line-height:1.3;margin:0 0 .65rem;font-weight:650}
.pdf-guided-editor fieldset{border:1px solid #c6c6c6;padding:.85rem;margin:1rem 0;min-width:0;background:#fff}
.pdf-guided-editor legend{font-weight:650;font-size:1rem;padding:0 .4rem}
.pdf-guided-editor .pge-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:.8rem 1rem;min-width:0}
.pdf-guided-editor .pge-field{display:flex;flex-direction:column;gap:.3rem;min-width:0;margin:0;font-weight:400}
.pdf-guided-editor .pge-label{font-weight:600;font-size:.86rem}
.pdf-guided-editor input,.pdf-guided-editor select,.pdf-guided-editor textarea,.pdf-guided-editor button{font:inherit;max-width:100%;border:1px solid #888;border-radius:3px;color:#202020;background:#fff;min-height:2.55rem;padding:.5rem .6rem}
.pdf-guided-editor input,.pdf-guided-editor select,.pdf-guided-editor textarea{width:100%;min-width:0}
.pdf-guided-editor input[type=checkbox]{width:1.2rem;min-height:1.2rem;height:1.2rem;align-self:flex-start;margin:.35rem 0}
.pdf-guided-editor textarea{resize:vertical;min-height:5rem;white-space:pre-wrap}
.pdf-guided-editor button{cursor:pointer;font-weight:550;line-height:1.3;white-space:normal}
.pdf-guided-editor button:hover:not(:disabled){background:#e8e8e8;border-color:#222}
.pdf-guided-editor button:focus-visible,.pdf-guided-editor input:focus-visible,.pdf-guided-editor select:focus-visible,.pdf-guided-editor textarea:focus-visible,.pdf-guided-editor summary:focus-visible{outline:2px solid #222;outline-offset:2px}
.pdf-guided-editor :disabled{opacity:1;color:#696969;background:#ededed;cursor:not-allowed;border-color:#bdbdbd}
.pdf-guided-editor small,.pdf-guided-editor .pge-help{font-size:.83rem;line-height:1.45;color:#505050;margin:.2rem 0 .35rem;overflow-wrap:anywhere}
.pdf-guided-editor .pge-status{border-left:3px solid #555;padding:.65rem .8rem;background:#efefef;margin:.5rem 0 1rem;overflow-wrap:anywhere}
.pdf-guided-editor .pge-warning{border:1px solid #555;border-left-width:4px;background:#e7e7e7;font-weight:550}
.pdf-guided-editor .pge-identity{font:400 .81rem/1.5 ui-monospace,SFMono-Regular,Consolas,monospace;color:#444;overflow-wrap:anywhere;padding:.6rem 0;border-bottom:1px solid #ccc}
.pdf-guided-editor .pge-selection{display:grid;grid-template-columns:minmax(12rem,1fr) minmax(14rem,2fr) auto;gap:.65rem;align-items:end;min-width:0}
.pdf-guided-editor .pge-toolbar{display:flex;gap:.5rem;flex-wrap:wrap;align-items:center;margin:.4rem 0;grid-column:1/-1}
.pdf-guided-editor .pge-toolbar span{font-size:.83rem;font-variant-numeric:tabular-nums}
.pdf-guided-editor .pge-toolbar button:first-child[data-focus=retain-edit]{color:white;background:#303030;border-color:#303030}
.pdf-guided-editor .pge-toolbar button:first-child[data-focus=retain-edit]:disabled{color:#696969;background:#ededed;border-color:#bdbdbd}
.pdf-guided-editor .pge-rectangle{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:.55rem;grid-column:1/-1}
.pdf-guided-editor .pge-geometry{display:block;width:auto;max-width:100%;height:17rem;justify-self:start;border:1px solid #aaa;background:white}
.pdf-guided-editor .pge-page-box{fill:#fff;stroke:#888;stroke-width:1}
.pdf-guided-editor .pge-review-box{fill:#e6e6e6;stroke:#222;stroke-width:2;stroke-dasharray:5 3}
.pdf-guided-editor .pge-item-box{fill:#808080;fill-opacity:.45;stroke:#222;stroke-width:1}
.pdf-guided-editor .pge-table-wrap{overflow:auto;border:1px solid #bdbdbd;max-width:100%;grid-column:1/-1;min-width:0}
.pdf-guided-editor table{border-collapse:collapse;width:100%;font-size:.83rem;margin:0;text-align:left}
.pdf-guided-editor caption{caption-side:top;text-align:left;font-weight:600;padding:.6rem;background:#eee}
.pdf-guided-editor th,.pdf-guided-editor td{padding:.5rem .6rem;border-bottom:1px solid #d0d0d0;vertical-align:top;text-align:left;overflow-wrap:anywhere}
.pdf-guided-editor th{background:#eee;font-weight:600}
.pdf-guided-editor tbody tr:nth-child(even){background:#f7f7f7}
.pdf-guided-editor td:nth-child(3){min-width:12rem;white-space:pre-wrap}
.pdf-guided-editor td input[type=text]{min-width:4.5rem}
.pdf-guided-editor details{min-width:0;grid-column:1/-1;border-top:1px solid #ddd;padding:.5rem 0}
.pdf-guided-editor summary{cursor:pointer;font-weight:550;overflow-wrap:anywhere}
.pdf-guided-editor pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:20rem;overflow:auto;font:400 .79rem/1.5 ui-monospace,SFMono-Regular,Consolas,monospace;background:#f1f1f1;border:1px solid #d0d0d0;padding:.7rem}
.pdf-guided-editor .pge-source-text{grid-column:1/-1;white-space:pre-wrap;overflow-wrap:anywhere;max-height:12rem;overflow:auto;border-left:2px solid #999;padding:.6rem;font-size:.83rem;background:#f5f5f5;margin:0}
.pdf-guided-editor .pge-empty{color:#555;margin:.5rem 0;grid-column:1/-1}
@media(max-width:760px){.pdf-guided-editor .pge-selection{grid-template-columns:minmax(0,1fr)}.pdf-guided-editor .pge-grid{grid-template-columns:minmax(0,1fr)}}
@media(max-width:430px){.pdf-guided-editor{padding:.65rem}.pdf-guided-editor fieldset{padding:.6rem}.pdf-guided-editor .pge-rectangle{grid-template-columns:repeat(2,minmax(0,1fr))}.pdf-guided-editor .pge-toolbar button{flex:1 1 10rem}.pdf-guided-editor td,.pdf-guided-editor th{padding:.4rem}.pdf-guided-editor .pge-geometry{height:13rem}.pdf-guided-editor .pge-selection select{font-size:.82rem}}
@media print{.pdf-guided-editor button{display:none}.pdf-guided-editor .pge-table-wrap{overflow:visible}.pdf-guided-editor pre{max-height:none}.pdf-guided-editor{break-inside:avoid}}
